#!/bin/sh
# GENERATED by validation/vteam/make_decks.py
# Runs every vteam-1 deck with Spectre; results land next to each deck.
# A failing deck is reported and the rest still run.
cd "$(dirname "$0")"
failed=''
spectre +escchars -format psfascii -raw off_train.raw +log off_train.log off_train.scs >/dev/null 2>&1 || failed="$failed off_train"
spectre +escchars -format psfascii -raw on_train.raw +log on_train.log on_train.scs >/dev/null 2>&1 || failed="$failed on_train"
spectre +escchars -format psfascii -raw s1_vteam.raw +log s1_vteam.log s1_vteam.scs >/dev/null 2>&1 || failed="$failed s1_vteam"
spectre +escchars -format psfascii -raw s2_vteam.raw +log s2_vteam.log s2_vteam.scs >/dev/null 2>&1 || failed="$failed s2_vteam"
spectre +escchars -format psfascii -raw amplitude_sweep.raw +log amplitude_sweep.log amplitude_sweep.scs >/dev/null 2>&1 || failed="$failed amplitude_sweep"
spectre +escchars -format psfascii -raw pulse_width_sweep.raw +log pulse_width_sweep.log pulse_width_sweep.scs >/dev/null 2>&1 || failed="$failed pulse_width_sweep"
spectre +escchars -format psfascii -raw read_disturb_hold.raw +log read_disturb_hold.log read_disturb_hold.scs >/dev/null 2>&1 || failed="$failed read_disturb_hold"
spectre +escchars -format psfascii -raw saturate_reverse.raw +log saturate_reverse.log saturate_reverse.scs >/dev/null 2>&1 || failed="$failed saturate_reverse"
spectre +escchars -format psfascii -raw dc_loop.raw +log dc_loop.log dc_loop.scs >/dev/null 2>&1 || failed="$failed dc_loop"
spectre +escchars -format psfascii -raw sine_memtorch.raw +log sine_memtorch.log sine_memtorch.scs >/dev/null 2>&1 || failed="$failed sine_memtorch"
[ -z "$failed" ] || { echo "FAILED decks:$failed"; exit 1; }
